plain-global.kujo.source:
func helper(value) { return value + 1 }
mut i := 0
mut total := 0
while i < 262144 { total += helper(i) i += 1 }
assert_equal(total, 34359869440)
print("PLAIN HELPER PASS")

journal_probe.kujo.source:
func helper(seed) { return seed }
export func make_work() {
    let seed := 1
    func work(count) {
        mut i := 0
        mut total := 0
        while i < count { total += helper(seed) i += 1 }
        return total
    }
    return work
}

task-state.kujo.source:
func factory() {
    mut total := 0
    func increment() { total += 1 return total }
    return increment
}
let increment := factory()
func run_work() {
    mut i := 0
    mut result := 0
    while i < 16384 { result = increment() i += 1 }
    return result
}
assert_equal(await await_task(spawn_task(run_work)), 16384)
print("TASK STATE PASS")

